"""boardcam.sketch — распознавание скетча, вызов vision-модели и запуск OpenSCAD."""

import json
import os
import re
import subprocess
import sys
import time
import urllib.request
import urllib.error

PROMPT = """You are a CAD assistant for a woodworker who cuts charcuterie / serving boards
on a 3-axis CNC router. You receive ONE photo of a hand-drawn pencil sketch of a board
with handwritten dimensions. Convert it into ONE valid OpenSCAD program.

THE PART:
Flat wooden stock machined as 2.5D: an outer profile (rectangle, rounded rectangle,
oval, leaf, clover or freeform) plus features cut from the top face: pockets (bowls,
dips, compartments), a juice groove, or a handle hole.

STRICT OUTPUT RULES:
1. Output ONLY OpenSCAD code. No markdown fences, no prose. Everything you want to
   say goes into OpenSCAD comments.
2. The file MUST have these sections in order:
   // === UNITS ===
   // units: mm
   // === PARAMETERS ===
   // snake_case variables with trailing comments
   // === ASSUMPTIONS ===
   // guesses and unreadable dimensions
   // === MODEL ===
   // 2D regions and 3D difference()
   // === CONTRACT ===
   // echo(boardcam_design = [...]) so boardcam CAM engine can parse it!

3. OpenSCAD code must define:
   - blank_x, blank_y, blank_thick (overall stock)
   - thick (part height)
   - pocket_depth (if pocket exists)
   - module outline_region(seg)  // 2D polygon/offset/hull of outer contour
   - module feature_region(k, seg) // 2D polygon/offset of pocket 1
   - module model() { difference() { translate([0,0,-thick]) linear_extrude(thick) outline_region(2.0); ... } }
   - echo(boardcam_design = [
       ["schema", 1], ["shape", "sketch"], ["variant", "custom"], ["units", "mm"],
       ["blank", [blank_x, blank_y, blank_thick]], ["origin", "corner"],
       ["thick", thick],
       ["outline", ["svg", "outline"]],
       ["features", [["pocket", 1, ["svg", "pocket:1"], pocket_depth, 6.35]]],
       ["derived", [["wall_min", 10], ["size", max(blank_x, blank_y)]]],
       ["messages", []]
     ]);
   - if (export == "") { model(); }
     else if (export == "outline") { outline_region(0.5); }
     else if (export == "pocket:1") { feature_region(1, 0.5); }
"""


def _clean_b64(b64_str: str) -> str:
    """Очищает префикс data:image/...;base64, если он есть."""
    if "," in b64_str:
        return b64_str.split(",", 1)[1]
    return b64_str.strip()


def get_available_models(ollama_host: str, deepseek_api_key: str = "") -> list:
    """Возвращает список доступных моделей (Ollama + DeepSeek API), с флагом vision."""
    models = []
    
    # 1. Опрос Ollama
    try:
        url = f"{ollama_host}/api/tags"
        req = urllib.request.Request(url, headers={"User-Agent": "boardcam"})
        with urllib.request.urlopen(req, timeout=5) as resp:
            data = json.loads(resp.read().decode("utf-8"))
            for m in data.get("models", []):
                name = m.get("name", "")
                caps = m.get("capabilities", []) or m.get("details", {}).get("capabilities", [])
                low = name.lower()
                is_vision = "vision" in caps or any(k in low for k in ("vl", "vision", "minicpm", "qwen3.5"))
                # красивое отображение имени
                display = name
                if "qwen2.5vl" in low or "qwen2.5-vl" in low:
                    display = f"Qwen 2.5 VL ({name})"
                elif "deepseek-v4-pro" in low:
                    display = f"DeepSeek V4 Pro 9B (локальная копия)"
                models.append({
                    "id": name,
                    "name": display,
                    "provider": "ollama",
                    "remote": False,
                    "vision": is_vision,
                    "is_default": False
                })
    except Exception as e:
        print(f"[boardcam.sketch] ошибка опроса Ollama: {e}", file=sys.stderr)

    # 2. DeepSeek API (удалённый)
    if deepseek_api_key:
        models.append({
            "id": "deepseek-flash",
            "name": "DeepSeek Flash (удалённый)",
            "provider": "deepseek",
            "remote": True,
            "is_default": False
        })

    # Сортировка: vision-модели первыми (qwen2.5vl → deepseek-v4-pro → ollama → remote), не-vision в конец
    if models:
        def _score(m):
            low = m["id"].lower()
            if m.get("vision") is False:
                return 100
            if "qwen2.5vl" in low or "qwen2.5-vl" in low:
                return 0
            if "deepseek-v4-pro" in low:
                return 1
            if m["provider"] == "ollama":
                return 2
            return 3
        models.sort(key=_score)
        models[0]["is_default"] = True

    return models


def call_vision(image_base64: str, prompt: str, model_name: str, ollama_host: str, deepseek_api_key: str = "") -> str:
    """Отправляет фото скетча в выбранную vision-модель и возвращает OpenSCAD код."""
    b64 = _clean_b64(image_base64)
    
    if model_name.startswith("deepseek-flash") or (model_name.startswith("deepseek") and not ollama_host):
        if not deepseek_api_key:
            raise RuntimeError("DEEPSEEK_API_KEY не задан")
        url = "https://api.deepseek.com/v1/chat/completions"
        headers = {
            "Authorization": f"Bearer {deepseek_api_key}",
            "Content-Type": "application/json"
        }
        payload = {
            "model": "deepseek-flash",
            "temperature": 0.2,
            "messages": [
                {
                    "role": "user",
                    "content": [
                        {"type": "image_url", "image_url": {"url": f"data:image/jpeg;base64,{b64}"}},
                        {"type": "text", "text": prompt or PROMPT}
                    ]
                }
            ]
        }
        req = urllib.request.Request(url, data=json.dumps(payload).encode("utf-8"), headers=headers, method="POST")
        with urllib.request.urlopen(req, timeout=180) as resp:
            data = json.loads(resp.read().decode("utf-8"))
            u = data.get("usage") or {}
            print(f"[DeepSeek] токены: prompt={u.get('prompt_tokens')}, completion={u.get('completion_tokens')}, всего={u.get('total_tokens')}", flush=True)
            return data["choices"][0]["message"]["content"]
    else:
        # Локальная Ollama через /api/chat
        url = f"{ollama_host}/api/chat"
        headers = {"Content-Type": "application/json"}
        payload = {
            "model": model_name,
            "stream": False,
            "messages": [
                {
                    "role": "user",
                    "content": prompt or PROMPT,
                    "images": [b64]
                }
            ]
        }
        req = urllib.request.Request(url, data=json.dumps(payload).encode("utf-8"), headers=headers, method="POST")
        with urllib.request.urlopen(req, timeout=300) as resp:
            data = json.loads(resp.read().decode("utf-8"))
            pc, ec = data.get("prompt_eval_count"), data.get("eval_count")
            print(f"[Ollama] токены: prompt={pc}, completion={ec}, всего={(pc or 0) + (ec or 0)}", flush=True)
            return data.get("message", {}).get("content", "")


def clean_scad_code(raw_code: str) -> str:
    """Удаляет markdown-обёртку ```openscad ... ``` и лишние пробелы."""
    code = raw_code.strip()
    code = re.sub(r"^```[a-zA-Z]*\s*", "", code)
    code = re.sub(r"\s*```$", "", code)
    return code.strip()


def open_in_openscad(scad_path: str) -> bool:
    """Запускает OpenSCAD GUI с открытым файлом scad_path."""
    if not os.path.isfile(scad_path):
        return False
    try:
        if sys.platform == "darwin":
            subprocess.Popen(["open", "-a", "OpenSCAD", scad_path])
            return True
        else:
            from .scad import runner
            exe = runner.find_openscad() or "openscad"
            subprocess.Popen([exe, scad_path])
            return True
    except Exception as e:
        print(f"[boardcam.sketch] ошибка запуска OpenSCAD: {e}", file=sys.stderr)
        return False


def get_shape_info(shape_name: str, shapes_dir: str) -> dict:
    """Возвращает информацию о файле фигуры (существование, время модификации, размер)."""
    p = os.path.join(shapes_dir, shape_name + ".scad")
    if not os.path.isfile(p):
        return {"exists": False, "mtime": 0, "size": 0, "file": p}
    st = os.stat(p)
    return {
        "exists": True,
        "mtime": st.st_mtime,
        "size": st.st_size,
        "file": p
    }
